  const ids = [...g.obligations.values()].filter((o) => o.ticket === ticket).flatMap((o) => o.cards)
  return [...new Set(ids)].map((id) => g.nodes.get(id)).filter((n): n is GraphNode => n?.kind === 'card')
}

